];

function buildGraph(edges) {
  const graph = new Map();
  for (const [a, b, weight] of edges) {
    if (!graph.has(a)) graph.set(a, []);
    if (!graph.has(b)) graph.set(b, []);
    graph.get(a).push([b, weight]);
    graph.get(b).push([a, weight]);
