    graph.get(a)!.push([b, weight]);
    graph.get(b)!.push([a, weight]);
  }
  return graph;
}

function dijkstra(graph: Graph, start: string): { dist: Map<string, number>; prev: Map<string, string> } {
  const dist = new Map<string, number>();
  const prev = new Map<string, string>();
  for (const node of graph.keys()) dist.set(node, Infinity);
  dist.set(start, 0);
  const queue: [number, string][] = [[0, start]];
  while (queue.length > 0) {
    queue.sort((x, y) => x[0] - y[0]);
    const [d, node] = queue.shift()!;
    if (d > dist.get(node)!) continue;
    for (const [neighbor, weight] of graph.get(node)!) {
      const nd = d + weight;
      if (nd < dist.get(neighbor)!) {
        dist.set(neighbor, nd);
        prev.set(neighbor, node);
        queue.push([nd, neighbor]);
      }
    }
  }
  return { dist, prev };
}

function pathTo(prev: Map<string, string>, start: string, target: string): string[] {
  const path = [target];
  while (path[path.length - 1] !== start) {
    path.push(prev.get(path[path.length - 1])!);
  }
  return path.reverse();
}

function main(): void {
